import React,{useEffect,useMemo,useState} from 'react';
import {supabase,supabaseReady} from './lib/supabase';

const FALLBACK=[
{id:1,name:'Latte',desc:'Espresso + leche cremosa.',price:49,cat:'Café',img:'/images/latte.jpg'},
{id:2,name:'Iced Latte',desc:'Café frío, mismo gran sabor.',price:55,cat:'Bebidas frías',img:'/images/iced-latte.jpg'},
{id:3,name:'Matcha Latte',desc:'Energía natural.',price:59,cat:'Café',img:'/images/matcha.jpg'},
{id:4,name:'Croissant',desc:'Hojaldre perfecto.',price:45,cat:'Postres',img:'/images/croissant.jpg'},
{id:5,name:'Bowl de Frutas',desc:'Frescura en cada bocado.',price:69,cat:'Comida',img:'/images/bowl.jpg'},
{id:6,name:'Smoothie Fresa',desc:'Natural y delicioso.',price:55,cat:'Bebidas frías',img:'/images/smoothie.jpg'}];
const CATS=['Todos','Café','Bebidas frías','Comida','Postres'];
const money=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(Number(n)||0);
const orderId=()=>`MRT-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${String(Date.now()).slice(-5)}`;

function pick(o,keys,def=null){for(const k of keys){if(o?.[k]!==undefined&&o?.[k]!==null)return o[k]}return def}
function normalizeProduct(p){return {id:pick(p,['id'],Date.now()),name:pick(p,['name','nombre'],'Producto'),desc:pick(p,['description','descripcion'],''),price:Number(pick(p,['price','base_price','precio'],0)),cat:pick(p,['category_name','category','categoria'],'Café'),img:pick(p,['image_url','image','imagen_url','imagen'],'/images/latte.jpg'),available:Boolean(pick(p,['is_available','available','disponible'],true))}}
function normalizeCategory(c){return pick(c,['name','nombre','title'],'Categoría')}

const DEMO_OPTIONS={
 'Latte':[
  {id:'size',name:'Tamaño',type:'single',required:true,values:[['Chico',0],['Mediano',6],['Grande',12]]},
  {id:'milk',name:'Tipo de leche',type:'single',required:true,values:[['Entera',0],['Deslactosada',0],['Almendra',0],['Avena',0]]},
  {id:'extras',name:'Extras',type:'multi',values:[['Shot extra',12],['Vainilla',8],['Caramelo',8],['Canela',8]]}],
 'Iced Latte':[
  {id:'size',name:'Tamaño',type:'single',required:true,values:[['Chico',0],['Mediano',6],['Grande',12]]},
  {id:'extras',name:'Extras',type:'multi',values:[['Vainilla',8],['Caramelo',8],['Shot extra',12]]}],
 'Matcha Latte':[
  {id:'size',name:'Tamaño',type:'single',required:true,values:[['Chico',0],['Mediano',6],['Grande',12]]},
  {id:'milk',name:'Tipo de leche',type:'single',required:true,values:[['Entera',0],['Deslactosada',0],['Almendra',0],['Avena',0]]},
  {id:'sweet',name:'Endulzante',type:'single',values:[['Sin azúcar',0],['Miel',5],['Stevia',0]]}],
 'Croissant':[{id:'fill',name:'Relleno',type:'single',values:[['Natural',0],['Chocolate',8],['Almendra',10]]}],
 'Bowl de Frutas':[{id:'extra',name:'Extras',type:'multi',values:[['Granola',6],['Yogurt',8],['Frutos rojos',10]]}],
 'Smoothie Fresa':[{id:'size',name:'Tamaño',type:'single',values:[['Chico',0],['Mediano',6],['Grande',12]]},{id:'extra',name:'Extras',type:'multi',values:[['Proteína',15],['Chía',7]]}]
};
function optionsFor(product){return DEMO_OPTIONS[product?.name]||[]}

export default function App(){
 const [screen,setScreen]=useState('home'),[cat,setCat]=useState('Todos');
 const [products,setProducts]=useState(FALLBACK),[categories,setCategories]=useState(CATS),[loading,setLoading]=useState(true);
 const [product,setProduct]=useState(null),[cart,setCart]=useState(()=>JSON.parse(localStorage.getItem('martie_cart')||'[]'));
 const [serverOptions,setServerOptions]=useState({});
 const [slotList,setSlotList]=useState([]);
 const [storeSettings,setStoreSettings]=useState(null);
 const [selected,setSelected]=useState({}),[qty,setQty]=useState(1),[editing,setEditing]=useState(null);
 const [checkout,setCheckout]=useState({name:'',phone:'',email:'',delivery:'pickup',address:'',exterior:'',interior:'',neighborhood:'',cp:'',reference:'',date:'',time:'',payment:'CARD_TERMINAL',notes:''});
 const [orders,setOrders]=useState(()=>JSON.parse(localStorage.getItem('martie_orders')||'[]'));
 const [auth,setAuth]=useState(()=>JSON.parse(localStorage.getItem('martie_demo_auth')||'null')),[authMode,setAuthMode]=useState('login'),[authForm,setAuthForm]=useState({email:'',password:'',name:''}),[authMsg,setAuthMsg]=useState('');
 const [club,setClub]=useState(()=>JSON.parse(localStorage.getItem('martie_club')||'{"points":0,"joined":"2026-09-07"}'));
 const [adminTab,setAdminTab]=useState('dashboard');
 useEffect(()=>{localStorage.setItem('martie_cart',JSON.stringify(cart))},[cart]);
 useEffect(()=>{localStorage.setItem('martie_orders',JSON.stringify(orders))},[orders]);
 useEffect(()=>{localStorage.setItem('martie_club',JSON.stringify(club))},[club]);
 useEffect(()=>{loadMenu(); if(supabaseReady){supabase.auth.getSession().then(({data})=>setAuth(data.session?.user||null)); const {data}=supabase.auth.onAuthStateChange((_e,s)=>setAuth(s?.user||null)); return()=>data.subscription.unsubscribe()}},[]);
 useEffect(()=>{if(!supabaseReady||!auth?.id)return;supabase.from('martie_orders').select('*').eq('user_id',auth.id).order('created_at',{ascending:false}).then(({data})=>{if(data?.length)setOrders(data.map(o=>({id:o.order_number,dbId:o.id,createdAt:o.created_at,total:Number(o.total),items:[],customer:{name:o.customer_name,phone:o.customer_phone,delivery:o.delivery_method,payment:o.payment_method},status:o.order_status,paymentStatus:o.payment_status})))})},[auth]);
 async function loadMenu(){
  if(!supabaseReady){setLoading(false);return}
  try{
   const [{data:cs,error:ce},{data:ps,error:pe}]=await Promise.all([supabase.from('martie_categories').select('*').order('sort_order'),supabase.from('martie_products').select('*').order('sort_order')]);
   const {data:st}=await supabase.from('martie_settings').select('*').eq('id',true).maybeSingle();if(st)setStoreSettings(st);
   if(!ce&&!pe&&ps?.length){
    const catMap=new Map((cs||[]).map(c=>[String(c.id),c.name]));
    setProducts(ps.map(p=>({id:p.id,name:p.name,desc:p.description,price:Number(p.base_price),cat:catMap.get(String(p.category_id))||'Café',img:p.image_url||'/images/latte.jpg',available:p.is_available})).filter(p=>p.available));
    if(cs?.length)setCategories(['Todos',...cs.map(normalizeCategory)]);
    const {data:os}=await supabase.from('martie_options').select('*').order('sort_order');
    const {data:vs}=await supabase.from('martie_option_values').select('*').order('sort_order');
    const map={};
    (os||[]).forEach(o=>{map[o.product_id]??=[];map[o.product_id].push({id:o.id,name:o.name,type:o.selection_type,required:o.is_required,values:(vs||[]).filter(v=>String(v.option_id)===String(o.id)&&v.is_available).map(v=>[v.name,Number(v.price_delta),v.id])})});
    setServerOptions(map);
   }else{
    const [{data:oldC,error:oldCE},{data:oldP,error:oldPE}]=await Promise.all([supabase.from('categories').select('*'),supabase.from('products').select('*')]);
    if(!oldCE&&!oldPE){if(oldP?.length)setProducts(oldP.map(normalizeProduct).filter(x=>x.available));if(oldC?.length)setCategories(['Todos',...oldC.map(normalizeCategory)])}
   }
  }catch(e){console.warn('Martie: usando menú demo.',e)}finally{setLoading(false)}
 }
 const shown=useMemo(()=>cat==='Todos'?products:products.filter(p=>p.cat===cat),[products,cat]);
 const cartCount=cart.reduce((a,x)=>a+x.qty,0),cartTotal=cart.reduce((a,x)=>a+x.qty*x.unitPrice,0);
 const opts=product?(serverOptions[product.id]?.length?serverOptions[product.id]:optionsFor(product)):[];
 const optionDelta=opts.reduce((sum,o)=>sum+(o.values||[]).filter(v=>selected[o.id]?.includes(v[0])).reduce((a,v)=>a+v[1],0),0);
 const currentUnit=product?product.price+optionDelta:0;
 const selectedLabels=opts.flatMap(o=>selected[o.id]||[]);
 const open=p=>{const oo=serverOptions[p.id]?.length?serverOptions[p.id]:optionsFor(p);setProduct(p);setSelected(Object.fromEntries(oo.map(o=>[o.id,o.type==='single'?[o.values[0][0]]:[]])));setQty(1);setEditing(null)};
 const edit=item=>{const p=products.find(x=>String(x.id)===String(item.productId))||{id:item.productId,name:item.name,desc:'',price:item.basePrice||item.unitPrice,img:item.img,cat:item.cat};setProduct(p);setEditing(item.id);setSelected(item.optionMap||{});setQty(item.qty)};
 const add=()=>{if(!product)return;const item={id:editing||Date.now(),productId:product.id,name:product.name,basePrice:product.price,unitPrice:currentUnit,qty,detail:selectedLabels.length?selectedLabels.join(' · '):'Sin personalización adicional',optionMap:selected,optionValueIds:opts.flatMap(o=>(selected[o.id]||[]).map(label=>{const v=o.values.find(x=>x[0]===label);return v?.[2]||null}).filter(Boolean)),img:product.img,cat:product.cat,note:''};setCart(c=>editing?c.map(x=>x.id===editing?item:x):[...c,item]);setProduct(null);setEditing(null)};
 const changeQty=(id,d)=>setCart(c=>c.map(x=>x.id===id?{...x,qty:Math.max(1,x.qty+d)}:x));
 const remove=id=>setCart(c=>c.filter(x=>x.id!==id));
 const goMenu=c=>{setCat(c);setScreen('menu');window.scrollTo({top:0,behavior:'smooth'})};
 const beginCheckout=()=>{if(cart.length){setScreen('checkout');setAuthMsg('')}};
 const updateCheckout=(k,v)=>setCheckout(x=>({...x,[k]:v}));
 const availableSlots=slotList;
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Merida'});
 useEffect(()=>{const localSlots=()=>{const arr=[];const now=new Date();let start;if(checkout.date===today){start=new Date(now.getTime()+40*60000);start.setSeconds(0,0);start.setMinutes(Math.ceil(start.getMinutes()/15)*15);}else{start=new Date();start.setHours(9,0,0,0);}const end=new Date();end.setHours(19,0,0,0);for(let t=new Date(start);t<end;t.setMinutes(t.getMinutes()+15))arr.push(`${String(t.getHours()).padStart(2,'0')}:${String(t.getMinutes()).padStart(2,'0')}`);return arr;};
if(!checkout.date){updateCheckout('date',today);return;}
if(supabaseReady){supabase.functions.invoke('available-slots',{body:{date:checkout.date}}).then(({data,error})=>{if(!error&&Array.isArray(data?.slots)&&data.slots.length){setSlotList(data.slots)}else{setSlotList(localSlots())}}).catch(()=>setSlotList(localSlots()))}else setSlotList(localSlots());},[checkout.date,supabaseReady,today]);
 const submitOrder=async()=>{
  if(!checkout.name||!checkout.phone||!checkout.time)return setAuthMsg('Completa nombre, teléfono y horario.');
  if(checkout.delivery==='delivery'&&(!checkout.address||!checkout.neighborhood||!checkout.cp))return setAuthMsg('Completa los datos de envío.');
  const payload={items:cart.map(x=>({product_id:x.productId,quantity:x.qty,option_value_ids:x.optionValueIds||[],notes:x.note||''})),customer:{name:checkout.name,phone:checkout.phone,email:checkout.email,address:{street:checkout.address,exterior:checkout.exterior,interior:checkout.interior,neighborhood:checkout.neighborhood,cp:checkout.cp,reference:checkout.reference}},delivery_method:checkout.delivery,scheduled_date:checkout.date,scheduled_time:checkout.time,payment_method:checkout.delivery==='delivery'?'TRANSFER':checkout.payment,notes:checkout.notes};
  if(supabaseReady){const {data,error}=await supabase.functions.invoke('create-order',{body:payload});if(error||data?.error){const raw=error?.message||data?.error||'';return setAuthMsg(raw.includes('Failed to send a request')||raw.includes('FunctionsHttpError')?'No pudimos conectar con el servidor de pedidos. El pedido NO se ha creado. Intenta nuevamente en unos segundos.':raw||'No se pudo crear el pedido.');}const o=data.order;const localOrder={id:o.order_number,dbId:o.id,createdAt:o.created_at,total:Number(o.total),items:cart,customer:{...checkout,payment:o.payment_method},status:o.order_status,paymentStatus:o.payment_status};setOrders(x=>[localOrder,...x]);supabase.functions.invoke('send-whatsapp',{body:{order_id:o.id,phone:String(storeSettings?.whatsapp_number||'9993596815'),body:`☕ NUEVO PEDIDO MARTIE\n\nPedido: ${o.order_number}\nCliente: ${checkout.name}\nTeléfono: ${checkout.phone}\nEntrega: ${checkout.delivery_method==='pickup'?'Recoger en Martie':'Envío'}\nHorario: ${o.scheduled_at ? new Date(o.scheduled_at).toLocaleString('es-MX',{dateStyle:'short',timeStyle:'short',timeZone:'America/Merida'}) : checkout.scheduled_at||'Por confirmar'}\nPago: ${o.payment_method==='TRANSFER'?'Transferencia':o.payment_method==='CARD_TERMINAL'?'Tarjeta en terminal':'Efectivo'}\nTotal: ${money(o.total)} MXN\n\n${o.payment_status==='WAITING_PROOF'?'⚠️ Esperando comprobante de transferencia.':'✅ Pedido recibido; pendiente de confirmación.'}`}}).catch(()=>{});setCart([]);setScreen('confirmation');setAuthMsg('');return}
  const id=orderId();const state=checkout.payment==='TRANSFER'||checkout.delivery==='delivery'?'PENDING_PAYMENT':'PENDING_CONFIRMATION';const o={id,createdAt:new Date().toISOString(),items:cart,total:cartTotal,customer:{...checkout},status:state,paymentStatus:checkout.payment==='TRANSFER'||checkout.delivery==='delivery'?'WAITING_PROOF':'PENDING'};setOrders(x=>[o,...x]);setCart([]);setScreen('confirmation');setAuthMsg('');
 };
 const waText=screen==='confirmation'&&orders[0]?`Hola Martie! Soy ${orders[0].customer.name}. Mi pedido es ${orders[0].id}. Total: ${money(orders[0].total)}. ${orders[0].paymentStatus==='WAITING_PROOF'?'Te envío mi comprobante de transferencia.':'Gracias!'}`:'';
 const whatsapp=`https://wa.me/${String(import.meta.env.VITE_MARTIE_WHATSAPP_NUMBER||storeSettings?.whatsapp_number||'').replace(/\D/g,'')}?text=${encodeURIComponent(waText)}`;
 const logout=async()=>{if(supabaseReady)await supabase.auth.signOut();setAuth(null)};
 const login=async()=>{setAuthMsg('');if(!authForm.email||!authForm.password)return setAuthMsg('Ingresa correo y contraseña.');if(authMode==='signup'&&!authForm.name.trim())return setAuthMsg('Ingresa tu nombre.');if(!supabaseReady){setAuth({email:authForm.email,user_metadata:{full_name:authForm.name||'Cliente Martie'}});setScreen('profile');return}if(authMode==='login'){const {data,error}=await supabase.auth.signInWithPassword({email:authForm.email,password:authForm.password});if(error)return setAuthMsg(error.message);if(data?.user){setAuth(data.user);setScreen('profile')}return}const {data,error}=await supabase.auth.signUp({email:authForm.email.trim(),password:authForm.password,options:{data:{full_name:authForm.name.trim()}}});if(error)return setAuthMsg(error.message);if(data?.session&&data?.user){setAuth(data.user);setScreen('profile');return}if(data?.user){setAuthMsg('Cuenta creada correctamente. Revisa tu correo para confirmar tu cuenta y después inicia sesión.');setAuthMode('login');setAuthForm(x=>({...x,password:''}));return}setAuthMsg('No pudimos completar la creación de la cuenta. Intenta nuevamente.')};
 return <div className="app">
  <header className="topbar"><button className="logoBtn" onClick={()=>setScreen('home')}><img src="/branding/martie-logo.png" alt="Martie"/></button><div className="topActions"><button className="iconBtn" onClick={()=>setScreen('search')} aria-label="Buscar">⌕</button>{(screen==='home'||screen==='menu')&&<button className="cartTop" onClick={()=>setScreen('cart')} aria-label="Abrir carrito"><span>🛒</span>{cartCount>0&&<b>{cartCount}</b>}</button>}<button className="clubTop" onClick={()=>setScreen('club')}>✦ Martie Club</button></div></header>
  {screen==='home'&&<Home products={products} menu={goMenu} open={open}/>} 
  {screen==='menu'&&<Menu cat={cat} setCat={setCat} shown={shown} open={open} categories={categories} loading={loading} />}
  {screen==='search'&&<Search products={products} open={open} back={()=>setScreen('home')}/>} 
  {screen==='club'&&<Club auth={auth} club={club} setScreen={setScreen}/>} 
  {screen==='profile'&&<Profile auth={auth} logout={logout} orders={orders} club={club} setScreen={setScreen}/>} 
  {screen==='cart'&&<Cart cart={cart} total={cartTotal} changeQty={changeQty} remove={remove} edit={edit} checkout={beginCheckout} setScreen={setScreen}/>}
  {screen==='orders'&&<Orders orders={orders} setScreen={setScreen}/>} 
  {screen==='tracking'&&<Tracking order={orders.find(o=>o.id===checkout.trackId)||orders[0]} />}
  {screen==='checkout'&&<Checkout settings={storeSettings} checkout={checkout} update={updateCheckout} cart={cart} total={cartTotal} slots={availableSlots} today={today} submit={submitOrder} error={authMsg} setScreen={setScreen} />}
  {screen==='confirmation'&&<Confirmation order={orders[0]} whatsapp={whatsapp} settings={storeSettings} setScreen={setScreen}/>} 
  {screen==='admin'&&<Admin products={products} setProducts={setProducts} orders={orders} adminTab={adminTab} setAdminTab={setAdminTab}/>} 
  {cartCount>0&&screen==='menu'&&<button className="cartBar" onClick={()=>setScreen('cart')}><span>🛒</span><b>{cartCount}</b><strong>Ver carrito · {money(cartTotal)}</strong></button>}
  <nav className="bottom"><Nav label="Inicio" icon="⌂" active={screen==='home'} onClick={()=>setScreen('home')}/><Nav label="Menú" icon="☕" active={screen==='menu'} onClick={()=>goMenu('Todos')}/><Nav label="Pedidos" icon="▣" active={['orders','tracking'].includes(screen)} onClick={()=>setScreen('orders')}/><Nav label="Perfil" icon="○" active={['profile','club'].includes(screen)} onClick={()=>setScreen(auth?'profile':'club')}/></nav>
  {product&&<ProductModal product={product} opts={opts} selected={selected} setSelected={setSelected} qty={qty} setQty={setQty} total={currentUnit} add={add} close={()=>{setProduct(null);setEditing(null)}}/>}
 </div>
}

function Home({menu,open,products}){return <main><section className="hero"><div className="heroText"><span className="kicker">BUENOS DÍAS, BUENOS MOMENTOS</span><h1>Tu café,<br/><em>a tu manera.</em></h1><p>Un espacio para bajar el ritmo, pedir algo rico y disfrutar el momento.</p><button className="dark" onClick={()=>menu('Todos')}>Ver menú <b>→</b></button></div><div className="heroArt"><div className="blob"/><img className="heroPhoto" src="/images/hero-latte.jpg" alt="Latte Martie"/><img className="character" src="/branding/martie-character.png" alt=""/><span className="scribble">mmm...</span></div><span className="heroHeart">♡</span></section><section className="section"><div className="heading"><div><span className="kicker">PARA HOY</span><h2>Lo que se antoja</h2></div><button onClick={()=>menu('Todos')}>Ver todo →</button></div><div className="chips">{['Café','Bebidas frías','Comida','Postres'].map(x=><button key={x} onClick={()=>menu(x)}>{x==='Bebidas frías'?'Bebidas':x}</button>)}</div><div className="miniGrid">{products.slice(0,3).map(p=><Mini key={p.id} p={p} open={open}/>)}</div></section><section className="moment section"><div><span className="kicker">MOMENTOS MARTIE</span><h2>Pequeños<br/><em>momentos,</em><br/>grandes días.</h2></div><img src="/branding/martie-character.png" alt=""/></section><section className="club section"><div><span className="kicker">MARTIE CLUB</span><h2>Más café,<br/>más momentos.</h2><button className="soft" onClick={()=>document.querySelector('.clubTop')?.click()}>Conocer beneficios →</button></div><img src="/branding/martie-character.png" alt=""/></section><footer><img src="/branding/martie-logo.png" alt="Martie"/><p>Momentos que saben mejor ♡</p></footer></main>}
function Menu({cat,setCat,shown,open,categories,loading}){return <main className="section page"><span className="kicker">MARTIE</span><h1>Nuestro menú</h1><p className="sub">Café, bebidas y más para cada momento.</p><div className="chips">{categories.map(c=><button className={cat===c?'active':''} key={c} onClick={()=>setCat(c)}>{c}</button>)}</div>{loading&&<div className="menuLoading">Cargando menú…</div>}<div className="grid">{shown.map(p=><Mini key={p.id} p={p} open={open} large/>)}</div>{!loading&&!shown.length&&<div className="menuLoading">No hay productos disponibles.</div>}<div className="inlineClub"><div><h2>Martie Club</h2><p>Acumula puntos en cada compra.</p></div><span className="clubPoints">10 pts / $100</span></div></main>}
function Search({products,open,back}){const [q,setQ]=useState('');const r=products.filter(p=>p.name.toLowerCase().includes(q.toLowerCase()));return <main className="section page"><button className="backBtn" onClick={back}>←</button><h1>Buscar</h1><input className="searchInput" autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="¿Qué se te antoja?"/><div className="grid searchGrid">{r.map(p=><Mini key={p.id} p={p} open={open} large/>)}</div></main>}
function Club({auth,club,setScreen}){return <main className="section profile"><div className="promo pink"><span className="kicker">MARTIE CLUB</span><h1>Más café,<br/>más momentos.</h1><p>Acumula puntos, recibe recompensas y celebra tu cumpleaños con Martie.</p>{auth?<div className="pointsBig"><strong>{club.points}</strong><span>puntos disponibles</span></div>:<button className="dark" onClick={()=>setScreen('profile')}>Crear mi cuenta →</button>}</div><div className="clubRules"><Rule icon="✦" title="Puntos" text="$100 MXN = 10 puntos"/><Rule icon="🎁" title="Recompensas" text="Canjea tus puntos por bebidas y productos."/><Rule icon="🎂" title="Cumpleaños" text="Una bebida gratis con 3 meses de membresía."/><Rule icon="↻" title="Ciclo anual" text="Tus puntos se renuevan un año después de tu registro."/></div></main>}
function Rule({icon,title,text}){return <div className="rule"><span>{icon}</span><div><b>{title}</b><small>{text}</small></div><strong>›</strong></div>}
function Profile({auth,logout,orders,club,setScreen}){if(!auth)return <Auth setScreen={setScreen}/>;return <main className="section profile"><div className="profileWelcome"><img src="/branding/martie-character.png" alt=""/><div><span className="kicker">HOLA</span><h1>{auth.user_metadata?.full_name||auth.email?.split('@')[0]||'Martie lover'}</h1><small>{auth.email}</small></div></div><div className="profileStats"><div><strong>{club.points}</strong><small>puntos</small></div><div><strong>{orders.length}</strong><small>pedidos</small></div></div><div className="list"><button onClick={()=>setScreen('club')}><span>✦</span><div><b>Martie Club</b><small>Recompensas y puntos</small></div><strong>›</strong></button><button onClick={()=>setScreen('orders')}><span>☕</span><div><b>Historial de pedidos</b><small>{orders.length} pedidos</small></div><strong>›</strong></button><button onClick={logout}><span>↪</span><div><b>Cerrar sesión</b><small>Salir de tu cuenta</small></div><strong>›</strong></button></div></main>}
function Auth({setScreen}){const [mode,setMode]=useState('login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[msg,setMsg]=useState('');const submit=async()=>{if(!email||!password||(mode==='signup'&&!name))return setMsg('Completa los campos.');if(!supabaseReady){localStorage.setItem('martie_demo_auth',JSON.stringify({email,user_metadata:{full_name:name||'Cliente Martie'}}));location.reload();return}const fn=mode==='login'?supabase.auth.signInWithPassword({email,password}):supabase.auth.signUp({email,password,options:{data:{full_name:name}}});const {error}=await fn;if(error)setMsg(error.message);else setScreen('profile')};return <main className="section auth"><img src="/branding/martie-logo.png" alt="Martie"/><span className="kicker">MARTIE CLUB</span><h1>{mode==='login'?'Bienvenido de vuelta.':'Crea tu cuenta.'}</h1><p>Compra como invitado o guarda tus momentos Martie.</p>{mode==='signup'&&<input placeholder="Nombre" value={name} onChange={e=>setName(e.target.value)}/>}<input type="email" placeholder="Correo electrónico" value={email} onChange={e=>setEmail(e.target.value)}/><input type="password" placeholder="Contraseña" value={password} onChange={e=>setPassword(e.target.value)}/>{msg&&<div className="formError">{msg}</div>}<button className="dark full" onClick={submit}>{mode==='login'?'Iniciar sesión':'Crear cuenta'} →</button><button className="linkBtn" onClick={()=>setMode(mode==='login'?'signup':'login')}>{mode==='login'?'¿No tienes cuenta? Crear una':'Ya tengo cuenta'}</button><button className="linkBtn" onClick={()=>setScreen('home')}>Continuar como invitado</button></main>}
function Cart({cart,total,changeQty,remove,edit,checkout,setScreen}){return <main className="section page"><button className="backBtn" onClick={()=>setScreen('menu')}>←</button><span className="kicker">TU PEDIDO</span><h1>Tu carrito</h1>{!cart.length?<div className="emptySmall"><div>🛒</div><h2>Tu carrito está vacío.</h2><button className="dark" onClick={()=>setScreen('menu')}>Ver menú →</button></div>:<><div className="cartList">{cart.map(x=><article className="cartLine" key={x.id}><img src={x.img} alt=""/><div><b>{x.name}</b><small>{x.detail}</small><span>{money(x.unitPrice)} c/u</span><div className="lineActions"><button onClick={()=>changeQty(x.id,-1)}>−</button><strong>{x.qty}</strong><button onClick={()=>changeQty(x.id,1)}>+</button><button onClick={()=>edit(x)}>Editar</button><button onClick={()=>remove(x.id)}>Eliminar</button></div></div><strong>{money(x.unitPrice*x.qty)}</strong></article>)}</div><div className="cartSummary"><span>Subtotal</span><b>{money(total)}</b><small>El envío se calcula según la zona.</small><button className="checkoutBtn" onClick={checkout}>Continuar pedido →</button></div></>}</main>}
function Orders({orders,setScreen}){return <main className="section page"><span className="kicker">MIS PEDIDOS</span><h1>Mis pedidos</h1>{!orders.length?<div className="emptySmall"><div>☕</div><h2>Aún no hay pedidos.</h2><p>Cuando hagas tu primer pedido aparecerá aquí.</p><button className="dark" onClick={()=>setScreen('menu')}>Ver menú →</button></div>:<div className="orderList">{orders.map(o=><article className="orderCard" key={o.id}><div className="orderTop"><div><span className="orderId">{o.id}</span><h3>{o.customer?.delivery==='delivery'?'Envío':'Recoger en Martie'}</h3></div><b>{money(o.total)}</b></div><p>{o.items.reduce((a,x)=>a+x.qty,0)} productos · {new Date(o.createdAt).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'})}</p><div className="statusPill">{labelStatus(o.status,o.paymentStatus)}</div><button className="outlineBtn" onClick={()=>{setScreen('tracking');window.__martieOrder=o}}>Ver seguimiento →</button></article>)}</div>}</main>}
function labelStatus(s,p){if(p==='WAITING_PROOF')return 'Esperando comprobante';if(s==='PENDING_CONFIRMATION')return 'Pedido recibido';if(s==='CONFIRMED')return 'Confirmado';if(s==='PREPARING')return 'Preparando';if(s==='READY')return 'Listo';if(s==='ON_THE_WAY')return 'En camino';if(s==='DELIVERED')return 'Entregado';return 'Pedido recibido'}
function Tracking({order}){const o=order||window.__martieOrder;if(!o)return <main className="section emptySmall"><h2>No encontramos el pedido.</h2></main>;const steps=['Pedido recibido','Pago confirmado','Preparando','Listo','En camino','Entregado'];return <main className="section page"><span className="kicker">SEGUIMIENTO</span><h1>{o.id}</h1><p className="sub">{o.customer?.delivery==='delivery'?'Te lo llevamos a tu dirección.':'Tu pedido estará listo para recoger.'}</p><div className="timeline">{steps.map((x,i)=><div className={'timeStep '+(i===0?'done':'')} key={x}><span>{i===0?'✓':i+1}</span><div><b>{x}</b><small>{i===0?'Pedido creado':i===1&&o.paymentStatus==='WAITING_PROOF'?'Pendiente de validar comprobante':'Pendiente'}</small></div></div>)}</div></main>}
function Checkout({checkout,update,cart,total,slots,today,submit,error,setScreen,settings}){const [step,setStep]=useState(1);const next=()=>setStep(s=>Math.min(4,s+1));const back=()=>step===1?setScreen('cart'):setStep(s=>s-1);const delivery=checkout.delivery==='delivery';const isTransfer=checkout.payment==='TRANSFER'||delivery;return <main className="section checkout"><div className="checkoutHead"><button className="backBtn" onClick={back}>←</button><div><span className="kicker">TU PEDIDO</span><h1>Finalizar pedido</h1></div></div><div className="steps"><span className={step>=1?'on':''}>1</span><i/><span className={step>=2?'on':''}>2</span><i/><span className={step>=3?'on':''}>3</span><i/><span className={step>=4?'on':''}>4</span></div>{step===1&&<div className="formCard"><h2>Tus datos</h2><input placeholder="Nombre completo" value={checkout.name} onChange={e=>update('name',e.target.value)}/><input placeholder="Teléfono / WhatsApp" value={checkout.phone} onChange={e=>update('phone',e.target.value)}/><input type="email" placeholder="Correo electrónico (opcional)" value={checkout.email} onChange={e=>update('email',e.target.value)}/><label className="choice"><input type="radio" checked={checkout.delivery==='pickup'} onChange={()=>update('delivery','pickup')}/><span><b>Recoger en Martie</b><small>Sin costo de envío</small></span></label><label className="choice"><input type="radio" checked={delivery} onChange={()=>{update('delivery','delivery');update('payment','TRANSFER')}}/><span><b>Envío</b><small>La tarifa se calcula por zona</small></span></label>{delivery&&<div className="addressGrid"><input placeholder="Dirección" value={checkout.address} onChange={e=>update('address',e.target.value)}/><input placeholder="Exterior" value={checkout.exterior} onChange={e=>update('exterior',e.target.value)}/><input placeholder="Interior (opcional)" value={checkout.interior} onChange={e=>update('interior',e.target.value)}/><input placeholder="Colonia" value={checkout.neighborhood} onChange={e=>update('neighborhood',e.target.value)}/><input placeholder="Código postal" value={checkout.cp} onChange={e=>update('cp',e.target.value)}/><input placeholder="Referencias" value={checkout.reference} onChange={e=>update('reference',e.target.value)}/></div>}<button className="checkoutBtn" onClick={next}>Continuar →</button></div>}{step===2&&<div className="formCard"><h2>¿Cuándo lo quieres?</h2><p className="scheduleToday">Hoy · {today.split('-').reverse().join('/')}</p><p className="hint">Elige uno de los horarios disponibles. Martie calcula automáticamente el tiempo de preparación.</p>{slots.length?<div className="slotGrid" role="group" aria-label="Horarios disponibles">{slots.map(x=><button type="button" key={x} className={`slotOption ${checkout.time===x?'selected':''}`} onClick={()=>update('time',x)}>{x}</button>)}</div>:<p className="emptySlots">No hay horarios disponibles por ahora. Intenta nuevamente más tarde.</p>}<button className="checkoutBtn" disabled={!checkout.time} onClick={next}>Continuar →</button></div>}{step===3&&<div className="formCard"><h2>Método de pago</h2>{delivery?<label className="choice selected"><input type="radio" checked readOnly/><span><b>Transferencia bancaria</b><small>Te mostraremos los datos y enviarás el comprobante por WhatsApp.</small></span></label>:<><label className="choice"><input type="radio" checked={checkout.payment==='CARD_TERMINAL'} onChange={()=>update('payment','CARD_TERMINAL')}/><span><b>Tarjeta en terminal</b><small>Pagas físicamente al recoger tu pedido.</small></span></label><label className="choice"><input type="radio" checked={checkout.payment==='CASH'} onChange={()=>update('payment','CASH')}/><span><b>Efectivo</b><small>Pagas al recoger tu pedido.</small></span></label><label className="choice"><input type="radio" checked={checkout.payment==='TRANSFER'} onChange={()=>update('payment','TRANSFER')}/><span><b>Transferencia</b><small>Validaremos tu comprobante antes de preparar.</small></span></label></>}{isTransfer&&<div className="bankBox paymentBankBox"><h3>Datos para transferir</h3><p className="bankIntro">Realiza la transferencia antes de confirmar tu pedido. El pedido quedará pendiente hasta validar tu comprobante.</p><p><b>Banco:</b> {settings?.bank_name||'Pendiente de configurar'}</p><p><b>Cuenta:</b> {settings?.bank_account||'Pendiente de configurar'}</p><p><b>CLABE:</b> {settings?.bank_clabe||'Pendiente de configurar'}</p><p><b>Titular:</b> {settings?.bank_holder||'Pendiente de configurar'}</p><p><b>Concepto:</b> Se generará con tu número de pedido</p><p><b>Total a transferir:</b> {money(total)} MXN</p></div>}<textarea placeholder="Notas para tu pedido (opcional)" value={checkout.notes} onChange={e=>update('notes',e.target.value)}/><button className="checkoutBtn" onClick={next}>Revisar pedido →</button></div>}{step===4&&<div className="formCard"><h2>Confirma tu pedido</h2><div className="review">{cart.map(x=><div key={x.id}><span>{x.qty} × {x.name}<small>{x.detail}</small></span><b>{money(x.qty*x.unitPrice)}</b></div>)}</div><div className="totalRow"><span>Total</span><strong>{money(total)}</strong></div><div className="reviewBox"><b>{checkout.delivery==='delivery'?'Envío':'Recoger en Martie'}</b><span>{checkout.date} · {checkout.time}</span><span>{checkout.name} · {checkout.phone}</span><span>{(checkout.delivery==='delivery'||checkout.payment==='TRANSFER')?'Transferencia bancaria':checkout.payment==='CASH'?'Efectivo':'Tarjeta en terminal'}</span></div>{error&&<div className="formError">{error}</div>}<button className="checkoutBtn" onClick={submit}>Confirmar pedido · {money(total)} →</button></div>}</main>}
function Confirmation({order,whatsapp,settings,setScreen}){const transfer=order?.paymentStatus==='WAITING_PROOF';return <main className="section confirmation"><div className="confirmIcon">{transfer?'↑':'✓'}</div><span className="kicker">{transfer?'COMPROBANTE REQUERIDO':'PEDIDO RECIBIDO'}</span><h1>{transfer?'Envía tu comprobante.':'¡Listo! Tu pedido está en camino.'}</h1><p className="sub">Pedido <b>{order?.id}</b> · {money(order?.total)}</p>{transfer&&<div className="bankBox"><h3>Datos para transferencia</h3><p><b>Banco:</b> {settings?.bank_name||'Pendiente de configurar'}</p><p><b>Cuenta:</b> {settings?.bank_account||'Pendiente de configurar'}</p><p><b>CLABE:</b> {settings?.bank_clabe||'Pendiente de configurar'}</p><p><b>Titular:</b> {settings?.bank_holder||'Pendiente de configurar'}</p><p><b>Concepto:</b> {order?.id}</p></div>}<a className="waBtn" href={whatsapp} target="_blank" rel="noreferrer">Abrir WhatsApp →</a><button className="outlineBtn wide" onClick={()=>setScreen('tracking')}>Ver seguimiento</button><button className="linkBtn" onClick={()=>setScreen('menu')}>Seguir comprando</button></main>}
function ProductModal({product,opts,selected,setSelected,qty,setQty,total,add,close}){const choose=(o,v)=>{const names=o.values.map(x=>x[0]);if(o.type==='multi'){const cur=selected[o.id]||[];setSelected({...selected,[o.id]:cur.includes(v)?cur.filter(x=>x!==v):[...cur,v]})}else setSelected({...selected,[o.id]:[v]})};return <div className="overlay" onClick={close}><section className="detail" onClick={e=>e.stopPropagation()}><button className="close" onClick={close}>×</button><img className="detailImg" src={product.img} alt=""/><div className="detailTitle"><div><h2>Personaliza tu {product.name}</h2><p>{product.desc}</p></div><strong>{money(total)}</strong></div>{opts.map(o=><div className="option" key={o.id}><h4>{o.name}{o.required&&<small className="required"> · obligatorio</small>}</h4><div>{o.values.map(v=><button key={v[0]} className={(selected[o.id]||[]).includes(v[0])?'selected':''} onClick={()=>choose(o,v[0])}>{v[0]}{v[1]?` + ${money(v[1])}`:''}</button>)}</div></div>)}<div className="qty"><button onClick={()=>setQty(Math.max(1,qty-1))}>−</button><b>{qty}</b><button onClick={()=>setQty(qty+1)}>+</button></div><button className="add" onClick={add}>Agregar al carrito <i>|</i> {money(total*qty)}</button></section></div>}
export function AdminRoute(){
 const [user,setUser]=useState(null),[checking,setChecking]=useState(true),[allowed,setAllowed]=useState(false),[msg,setMsg]=useState('');
 const [email,setEmail]=useState(''),[password,setPassword]=useState('');
 const [products,setProducts]=useState(FALLBACK),[orders,setOrders]=useState([]),[adminTab,setAdminTab]=useState('dashboard');
 useEffect(()=>{
  if(!supabaseReady){setChecking(false);setMsg('Configura las variables de Supabase para entrar al administrador.');return;}
  let active=true;
  const verifyAdmin=async(u)=>{
   if(!u)return false;
   const {data:staff,error:staffError}=await supabase.from('martie_staff').select('role,is_active').eq('user_id',u.id).maybeSingle();
   if(!staffError && staff?.role==='admin' && staff?.is_active!==false) return true;
   const {data:isAdmin}=await supabase.rpc('martie_is_admin');
   return isAdmin===true;
  };
  supabase.auth.getSession().then(async ({data})=>{
   if(!active)return;
   const u=data.session?.user||null; setUser(u);
   if(u){const ok=await verifyAdmin(u); if(active){setAllowed(ok); if(!ok)setMsg('Tu cuenta no tiene permisos de administrador.');}}
   setChecking(false);
  });
  const {data}=supabase.auth.onAuthStateChange(async (_e,s)=>{
   const u=s?.user||null; setUser(u);
   if(!u){setAllowed(false);setChecking(false);return;}
   const {data:staff,error:staffError}=await supabase.from('martie_staff').select('role,is_active').eq('user_id',u.id).maybeSingle();
   let ok=!staffError && staff?.role==='admin'&&staff?.is_active!==false;
   if(!ok){const {data:isAdmin}=await supabase.rpc('martie_is_admin'); ok=isAdmin===true;}
   if(active){setAllowed(ok);setMsg(ok?'':'Tu cuenta no tiene permisos de administrador.');setChecking(false);}
  });
  return()=>{active=false;data.subscription.unsubscribe()};
 },[]);
 const loginAdmin=async()=>{setMsg('');if(!email.trim()||!password)return setMsg('Ingresa correo y contraseña.');setChecking(true);const {data,error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error){setChecking(false);return setMsg(error.message)}const u=data.user;if(u){const {data:isAdmin,error:ae}=await supabase.rpc('martie_is_admin');if(ae||isAdmin!==true){await supabase.auth.signOut();setChecking(false);return setMsg('Esta cuenta no tiene permisos de administrador.')}setAllowed(true);setUser(u)}setChecking(false)};
 const logout=async()=>{await supabase.auth.signOut();setAllowed(false);setUser(null);setPassword('')};
 if(checking)return <main className="section admin"><span className="kicker">MARTIE</span><h1>Administración</h1><p className="hint">Verificando acceso…</p></main>;
 if(!user||!allowed)return <main className="section admin adminLogin"><div className="adminLoginCard"><img src="/branding/martie-logo.png" alt="Martie"/><span className="kicker">MARTIE · ADMIN</span><h1>Administración</h1><p>Inicia sesión con la cuenta administrativa para continuar.</p><input type="email" placeholder="Correo administrativo" value={email} onChange={e=>setEmail(e.target.value)} onKeyDown={e=>e.key==='Enter'&&loginAdmin()}/><input type="password" placeholder="Contraseña" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>e.key==='Enter'&&loginAdmin()}/>{msg&&<div className="formError">{msg}</div>}<button className="dark full" onClick={loginAdmin}>Entrar al administrador →</button><button className="outlineBtn wide" onClick={()=>window.location.href='/'}>← Volver a Martie</button></div></main>;
 return <Admin products={products} setProducts={setProducts} orders={orders} adminTab={adminTab} setAdminTab={setAdminTab} onLogout={logout}/>;
}

function Admin({products,setProducts,orders,adminTab,setAdminTab,onLogout}){
 const [ready,setReady]=useState(false),[rows,setRows]=useState([]),[cats,setCats]=useState([]),[zones,setZones]=useState([]),[settings,setSettings]=useState(null),[msg,setMsg]=useState('');
 const [editing,setEditing]=useState(null),[form,setForm]=useState({name:'',description:'',base_price:'',category_id:'',image_url:'',sort_order:0,is_featured:false,is_new:false,is_bestseller:false});
 const [catForm,setCatForm]=useState({name:'',sort_order:0}),[editingCat,setEditingCat]=useState(null);
 const [zoneForm,setZoneForm]=useState({name:'',fee:0}),[editingZone,setEditingZone]=useState(null);
 useEffect(()=>{if(!supabaseReady){setMsg('Configura Supabase para usar Administración.');return}load()},[]);
 async function load(){
  setMsg('');
  const {data:u}=await supabase.auth.getUser();
  if(!u?.user){setMsg('Sesión administrativa no disponible. Vuelve a iniciar sesión en /admin.');return}
  const {data:staff,error:staffError}=await supabase.from('martie_staff').select('role,is_active').eq('user_id',u.user.id).maybeSingle();
  let isAdmin=!staffError && staff?.role==='admin'&&staff?.is_active!==false;
  if(!isAdmin){const {data:rpcAdmin}=await supabase.rpc('martie_is_admin');isAdmin=rpcAdmin===true;}
  if(!isAdmin){setMsg('Tu cuenta no tiene permisos de administrador.');return}
  const [{data:o},{data:c},{data:p},{data:s},{data:z}]=await Promise.all([
   supabase.from('martie_orders').select('*').order('created_at',{ascending:false}),
   supabase.from('martie_categories').select('*').order('sort_order'),
   supabase.from('martie_products').select('*').order('sort_order'),
   supabase.from('martie_settings').select('*').eq('id',true).single(),
   supabase.from('martie_delivery_zones').select('*').order('name')
  ]);
  setRows(o||[]);setCats(c||[]);setZones(z||[]);
  setProducts((p||[]).map(x=>({id:x.id,name:x.name,desc:x.description,price:Number(x.base_price),cat:(c||[]).find(y=>y.id===x.category_id)?.name||'Sin categoría',img:x.image_url||'/images/latte.jpg',available:x.is_available,isFeatured:x.is_featured,isNew:x.is_new,isBestseller:x.is_bestseller})));
  setSettings(s||null);setReady(true);
 }
 const beginProduct=p=>{setEditing(p.id);setForm({name:p.name||'',description:p.desc||'',base_price:p.price??'',category_id:cats.find(c=>c.name===p.cat)?.id||'',image_url:p.img||'',sort_order:products.find(x=>x.id===p.id)?.sort_order||0,is_featured:!!p.isFeatured,is_new:!!p.isNew,is_bestseller:!!p.isBestseller});window.scrollTo({top:0,behavior:'smooth'})};
 const clearProduct=()=>{setEditing(null);setForm({name:'',description:'',base_price:'',category_id:cats[0]?.id||'',image_url:'/images/latte.jpg',sort_order:0,is_featured:false,is_new:false,is_bestseller:false})};
 const saveProduct=async()=>{
  if(!form.name.trim()||form.base_price==='')return setMsg('Nombre y precio son obligatorios.');
  const payload={name:form.name.trim(),description:form.description||'',base_price:Number(form.base_price),category_id:form.category_id||null,image_url:form.image_url||'/images/latte.jpg',sort_order:Number(form.sort_order)||0,is_featured:!!form.is_featured,is_new:!!form.is_new,is_bestseller:!!form.is_bestseller,updated_at:new Date().toISOString()};
  const result=editing?await supabase.from('martie_products').update(payload).eq('id',editing):await supabase.from('martie_products').insert(payload);
  if(result.error)return setMsg(result.error.message);setMsg(editing?'Producto actualizado.':'Producto creado.');clearProduct();load();
 };
 const toggleProduct=async p=>{const {error}=await supabase.from('martie_products').update({is_available:p.available===false,updated_at:new Date().toISOString()}).eq('id',p.id);if(error)setMsg(error.message);else load()};
 const saveCategory=async()=>{if(!catForm.name.trim())return setMsg('Escribe el nombre de la categoría.');const payload={name:catForm.name.trim(),sort_order:Number(catForm.sort_order)||0};const r=editingCat?await supabase.from('martie_categories').update(payload).eq('id',editingCat):await supabase.from('martie_categories').insert(payload);if(r.error)return setMsg(r.error.message);setCatForm({name:'',sort_order:0});setEditingCat(null);setMsg('Categoría guardada.');load()};
 const toggleCategory=async c=>{const {error}=await supabase.from('martie_categories').update({is_active:!c.is_active}).eq('id',c.id);if(error)setMsg(error.message);else load()};
 const saveZone=async()=>{if(!zoneForm.name.trim())return setMsg('Escribe el nombre de la zona.');const payload={name:zoneForm.name.trim(),fee:Number(zoneForm.fee)||0};const r=editingZone?await supabase.from('martie_delivery_zones').update(payload).eq('id',editingZone):await supabase.from('martie_delivery_zones').insert(payload);if(r.error)return setMsg(r.error.message);setZoneForm({name:'',fee:0});setEditingZone(null);setMsg('Zona guardada.');load()};
 const toggleZone=async z=>{const {error}=await supabase.from('martie_delivery_zones').update({is_active:!z.is_active}).eq('id',z.id);if(error)setMsg(error.message);else load()};
 const advance=async o=>{const next=o.order_status==='PENDING_CONFIRMATION'?'CONFIRMED':o.order_status==='CONFIRMED'?'PREPARING':o.order_status==='PREPARING'?'READY':o.order_status==='READY'?(o.delivery_method==='delivery'?'ON_THE_WAY':'DELIVERED'):o.order_status==='ON_THE_WAY'?'DELIVERED':o.order_status;if(!['PENDING_CONFIRMATION','CONFIRMED','PREPARING','READY','ON_THE_WAY'].includes(o.order_status))return;const {data,error}=await supabase.functions.invoke('admin-update-order',{body:{order_id:o.id,order_status:next}});if(error||data?.error)return setMsg(error?.message||data?.error);supabase.functions.invoke('send-status-whatsapp',{body:{order_id:o.id,status:next}}).catch(()=>{});load()};
 const review=async(o,approve)=>{const payment_status=approve?'PAID':'REJECTED';const order_status=approve?'CONFIRMED':'PENDING_PAYMENT';const {data,error}=await supabase.functions.invoke('admin-update-order',{body:{order_id:o.id,payment_status,order_status}});if(error||data?.error)setMsg(error?.message||data?.error);else{if(approve)supabase.functions.invoke('send-status-whatsapp',{body:{order_id:o.id,status:'CONFIRMED'}}).catch(()=>{});load()}};
 const saveSettings=async()=>{if(!settings)return;const payload={store_name:settings.store_name||'Martie',opening_time:settings.opening_time,closing_time:settings.closing_time,prep_minutes:Number(settings.prep_minutes),slot_interval:Number(settings.slot_interval),capacity_per_slot:Number(settings.capacity_per_slot),whatsapp_number:settings.whatsapp_number,bank_name:settings.bank_name,bank_account:settings.bank_account,bank_clabe:settings.bank_clabe,bank_holder:settings.bank_holder,pickup_address:settings.pickup_address,updated_at:new Date().toISOString()};const {error}=await supabase.from('martie_settings').update(payload).eq('id',true);setMsg(error?'Error: '+error.message:'Configuración guardada correctamente.');if(!error)load()};
 if(!ready)return <main className="section admin"><span className="kicker">MARTIE</span><h1>Administración</h1><div className="formError">{msg||'Verificando permisos…'}</div></main>;
 return <main className="section admin">
  <div className="adminHead"><div><span className="kicker">MARTIE</span><h1>Administración</h1></div><div className="adminHeadActions"><button className="outlineBtn" onClick={()=>{window.location.href='/'}}>← Volver a Martie</button><button className="outlineBtn" onClick={onLogout}>Cerrar sesión</button><span className="adminBadge">ADMIN</span></div></div>
  {msg&&<div className="formError">{msg}</div>}
  <div className="adminTabs">{['dashboard','products','categories','options','zones','orders','settings'].map(x=><button className={adminTab===x?'active':''} onClick={()=>setAdminTab(x)} key={x}>{x==='dashboard'?'Resumen':x==='products'?'Productos':x==='categories'?'Categorías':x==='options'?'Opciones':x==='zones'?'Envíos':x==='orders'?'Pedidos':'Configuración'}</button>)}</div>
  {adminTab==='dashboard'&&<div className="adminStats"><Stat n={rows.length} t="Pedidos"/><Stat n={money(rows.reduce((a,x)=>a+Number(x.total),0))} t="Ventas"/><Stat n={products.length} t="Productos"/><Stat n={rows.filter(x=>x.payment_status==='WAITING_PROOF').length} t="Transferencias pendientes"/></div>}
  {adminTab==='products'&&<div className="adminPanel"><div className="panelTitle"><div><h2>{editing?'Editar producto':'Productos'}</h2><p className="hint">Todo lo que cambies aquí se refleja en el menú para nuevos pedidos.</p></div>{editing&&<button className="outlineBtn" onClick={clearProduct}>Cancelar</button>}</div><div className="adminForm productForm"><input placeholder="Nombre" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><input placeholder="Precio" type="number" min="0" value={form.base_price} onChange={e=>setForm({...form,base_price:e.target.value})}/><select value={form.category_id} onChange={e=>setForm({...form,category_id:e.target.value})}><option value="">Sin categoría</option>{cats.filter(c=>c.is_active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><input placeholder="URL de imagen" value={form.image_url} onChange={e=>setForm({...form,image_url:e.target.value})}/><input placeholder="Orden" type="number" value={form.sort_order} onChange={e=>setForm({...form,sort_order:e.target.value})}/><textarea className="adminTextarea" placeholder="Descripción" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/><label className="adminCheck"><input type="checkbox" checked={form.is_featured} onChange={e=>setForm({...form,is_featured:e.target.checked})}/> Destacado</label><label className="adminCheck"><input type="checkbox" checked={form.is_new} onChange={e=>setForm({...form,is_new:e.target.checked})}/> Nuevo</label><label className="adminCheck"><input type="checkbox" checked={form.is_bestseller} onChange={e=>setForm({...form,is_bestseller:e.target.checked})}/> Más vendido</label><button className="dark" onClick={saveProduct}>{editing?'Guardar cambios':'Agregar producto'}</button></div>{products.map(p=><div className="adminRow" key={p.id}><span><b>{p.name}</b><small>{p.cat} · {money(p.price)} {p.isFeatured?'· Destacado':''} {p.isNew?'· Nuevo':''} {p.isBestseller?'· Más vendido':''}</small></span><div><button onClick={()=>beginProduct(p)}>Editar</button><button onClick={()=>toggleProduct(p)}>{p.available===false?'Activar':'Desactivar'}</button></div></div>)}</div>}
  {adminTab==='categories'&&<div className="adminPanel"><div className="panelTitle"><div><h2>Categorías</h2><p className="hint">Crea, renombra, ordena y activa/desactiva categorías del menú.</p></div></div><div className="adminForm"><input placeholder="Nombre de categoría" value={catForm.name} onChange={e=>setCatForm({...catForm,name:e.target.value})}/><input placeholder="Orden" type="number" value={catForm.sort_order} onChange={e=>setCatForm({...catForm,sort_order:e.target.value})}/><button className="dark" onClick={saveCategory}>{editingCat?'Guardar cambios':'Agregar categoría'}</button></div>{cats.map(c=><div className="adminRow" key={c.id}><span><b>{c.name}</b><small>Orden {c.sort_order} · {c.is_active?'Activa':'Inactiva'}</small></span><div><button onClick={()=>{setEditingCat(c.id);setCatForm({name:c.name,sort_order:c.sort_order})}}>Editar</button><button onClick={()=>toggleCategory(c)}>{c.is_active?'Desactivar':'Activar'}</button></div></div>)}</div>}
  {adminTab==='options'&&<OptionAdmin products={products}/>} 
  {adminTab==='zones'&&<div className="adminPanel"><h2>Zonas de envío</h2><p className="hint">Define el nombre y costo de cada zona. La tarifa se usa en nuevos pedidos.</p><div className="adminForm"><input placeholder="Zona / colonia / cobertura" value={zoneForm.name} onChange={e=>setZoneForm({...zoneForm,name:e.target.value})}/><input placeholder="Costo" type="number" min="0" value={zoneForm.fee} onChange={e=>setZoneForm({...zoneForm,fee:e.target.value})}/><button className="dark" onClick={saveZone}>{editingZone?'Guardar cambios':'Agregar zona'}</button></div>{zones.map(z=><div className="adminRow" key={z.id}><span><b>{z.name}</b><small>{money(z.fee)} · {z.is_active?'Activa':'Inactiva'}</small></span><div><button onClick={()=>{setEditingZone(z.id);setZoneForm({name:z.name,fee:z.fee})}}>Editar</button><button onClick={()=>toggleZone(z)}>{z.is_active?'Desactivar':'Activar'}</button></div></div>)}</div>}
  {adminTab==='orders'&&<div className="adminPanel"><h2>Pedidos</h2>{!rows.length&&<p className="hint">No hay pedidos todavía.</p>}{rows.map(o=><div className="adminRow" key={o.id}><span><b>{o.order_number}</b><small>{o.customer_name} · {o.scheduled_date} {String(o.scheduled_time).slice(0,5)} · {o.delivery_method==='delivery'?'Envío':'Recoger'}</small><small>Pago: {o.payment_status} · Estado: {o.order_status}</small></span><b>{money(o.total)}</b><div><button onClick={()=>advance(o)}>Siguiente</button>{o.payment_status==='WAITING_PROOF'&&<><button onClick={()=>review(o,true)}>Aprobar transferencia</button><button onClick={()=>review(o,false)}>Rechazar</button></>}</div></div>)}</div>}
  {adminTab==='settings'&&settings&&<div className="adminPanel"><h2>Configuración</h2><p className="hint">Estos datos controlan horarios, WhatsApp, transferencia y recogida.</p>{[['store_name','Nombre del negocio'],['opening_time','Apertura'],['closing_time','Cierre'],['prep_minutes','Preparación (min)'],['slot_interval','Intervalo (min)'],['capacity_per_slot','Capacidad por horario'],['whatsapp_number','WhatsApp de confirmaciones'],['bank_name','Banco'],['bank_account','Cuenta'],['bank_clabe','CLABE'],['bank_holder','Titular'],['pickup_address','Dirección de recogida']].map(([k,l])=><label className="settingEdit" key={k}>{l}<input value={settings[k]??''} onChange={e=>setSettings({...settings,[k]:e.target.value})}/></label>)}<button className="dark" onClick={saveSettings}>Guardar configuración</button><p className="hint">Zona horaria: {settings.timezone}. La disponibilidad definitiva se valida en servidor.</p></div>}
 </main>
}
function OptionAdmin({products}){
 const [pid,setPid]=useState(products[0]?.id||''),[options,setOptions]=useState([]),[name,setName]=useState(''),[value,setValue]=useState(''),[delta,setDelta]=useState(''),[type,setType]=useState('single'),[required,setRequired]=useState(false),[msg,setMsg]=useState('');
 const [editingOption,setEditingOption]=useState(null),[editingValue,setEditingValue]=useState(null),[editName,setEditName]=useState(''),[editDelta,setEditDelta]=useState('');
 const load=async()=>{if(!pid||!supabaseReady)return;const {data,error}=await supabase.from('martie_options').select('*').eq('product_id',pid).order('sort_order');if(error)setMsg(error.message);else setOptions(data||[])};
 useEffect(()=>{if(!pid&&products[0])setPid(products[0].id)},[products]);useEffect(()=>{load()},[pid]);
 const addOption=async()=>{if(!name.trim())return;const {error}=await supabase.from('martie_options').insert({product_id:pid,name:name.trim(),selection_type:type,is_required:required});if(error)setMsg(error.message);else{setName('');setRequired(false);setMsg('Opción agregada.');load()}};
 const saveOption=async o=>{const {error}=await supabase.from('martie_options').update({name:editName.trim(),selection_type:o.selection_type,is_required:o.is_required}).eq('id',o.id);if(error)setMsg(error.message);else{setEditingOption(null);load()}};
 const deleteOption=async o=>{if(!window.confirm(`¿Eliminar la opción "${o.name}" y sus valores?`))return;const {error}=await supabase.from('martie_options').delete().eq('id',o.id);if(error)setMsg(error.message);else load()};
 const addValue=async o=>{if(!value.trim())return;const {error}=await supabase.from('martie_option_values').insert({option_id:o.id,name:value.trim(),price_delta:Number(delta||0)});if(error)setMsg(error.message);else{setValue('');setDelta('');setMsg('Valor agregado.');load()}};
 const saveValue=async v=>{const {error}=await supabase.from('martie_option_values').update({name:editName.trim(),price_delta:Number(editDelta||0)}).eq('id',v.id);if(error)setMsg(error.message);else{setEditingValue(null);load()}};
 const toggleValue=async v=>{const {error}=await supabase.from('martie_option_values').update({is_available:!v.is_available}).eq('id',v.id);if(error)setMsg(error.message);else load()};
 const deleteValue=async v=>{if(!window.confirm(`¿Eliminar "${v.name}"?`))return;const {error}=await supabase.from('martie_option_values').delete().eq('id',v.id);if(error)setMsg(error.message);else load()};
 return <div className="adminPanel"><h2>Opciones y personalización</h2><select value={pid} onChange={e=>setPid(e.target.value)}>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><p className="hint">Edita tamaños, leche, extras y cualquier opción. Los cambios aplican a nuevos pedidos.</p><div className="adminForm"><input placeholder="Nueva opción: Tamaño, Leche..." value={name} onChange={e=>setName(e.target.value)}/><select value={type} onChange={e=>setType(e.target.value)}><option value="single">Una opción</option><option value="multi">Varias opciones</option></select><label className="adminCheck"><input type="checkbox" checked={required} onChange={e=>setRequired(e.target.checked)}/> Obligatoria</label><button className="dark" onClick={addOption}>Agregar grupo</button></div>{msg&&<div className="formError">{msg}</div>}{options.map(o=><div className="optionAdmin" key={o.id}>{editingOption===o.id?<div className="adminForm"><input value={editName} onChange={e=>setEditName(e.target.value)}/><button onClick={()=>saveOption(o)}>Guardar</button><button onClick={()=>setEditingOption(null)}>Cancelar</button></div>:<><b>{o.name}</b><small>{o.selection_type==='multi'?'Múltiples':'Una'} {o.is_required?'· obligatoria':''} <button className="inlineAdminBtn" onClick={()=>{setEditingOption(o.id);setEditName(o.name)}}>Editar</button><button className="inlineAdminBtn" onClick={()=>deleteOption(o)}>Eliminar</button></small></>}<div className="adminForm"><input placeholder="Nuevo valor" value={value} onChange={e=>setValue(e.target.value)}/><input placeholder="+$" type="number" value={delta} onChange={e=>setDelta(e.target.value)}/><button onClick={()=>addValue(o)}>Agregar valor</button></div><OptionValues optionId={o.id} onEdit={v=>{setEditingValue(v.id);setEditName(v.name);setEditDelta(v.price_delta)}} onToggle={toggleValue} onDelete={deleteValue} editingValue={editingValue} editName={editName} editDelta={editDelta} setEditName={setEditName} setEditDelta={setEditDelta} saveValue={saveValue} cancelEdit={()=>setEditingValue(null)}/></div>)}</div>
}
function OptionValues({optionId,onEdit,onToggle,onDelete,editingValue,editName,editDelta,setEditName,setEditDelta,saveValue,cancelEdit}){const [values,setValues]=useState([]);const load=async()=>{const {data}=await supabase.from('martie_option_values').select('*').eq('option_id',optionId).order('sort_order');setValues(data||[])};useEffect(()=>{load()},[optionId]);useEffect(()=>{const fn=()=>load();window.addEventListener('martie:reload-options',fn);return()=>window.removeEventListener('martie:reload-options',fn)},[optionId]);return <div className="optionValues">{values.map(v=>editingValue===v.id?<div className="editableValue" key={v.id}><input value={editName} onChange={e=>setEditName(e.target.value)}/><input type="number" value={editDelta} onChange={e=>setEditDelta(e.target.value)}/><button onClick={()=>saveValue(v)}>Guardar</button><button onClick={cancelEdit}>Cancelar</button></div>:<span key={v.id} className={!v.is_available?'inactive':''}>{v.name} {Number(v.price_delta)?`+ ${money(v.price_delta)}`:''}<button onClick={()=>onEdit(v)}>Editar</button><button onClick={()=>onToggle(v)}>{v.is_available?'Ocultar':'Activar'}</button><button onClick={()=>onDelete(v)}>×</button></span>)}</div>}
function Stat({n,t}){return <div className="stat"><strong>{n}</strong><small>{t}</small></div>}
function Mini({p,open,large}){return <article className={large?'card large':'mini'} onClick={()=>open(p)}><img src={p.img} alt={p.name}/><div><div><b>{p.name}</b><small>{p.desc}</small></div><strong>{money(p.price)}</strong></div>{large&&<button className="personalizeBtn" onClick={e=>{e.stopPropagation();open(p)}}>Personalizar</button>}</article>}
function Nav({label,icon,active,onClick}){return <button className={active?'nav active':'nav'} onClick={onClick}><span>{icon}</span><small>{label}</small></button>}
